class Solution(object):
    def areNumbersAscending(self, s):
        """
        :type s: str
        :rtype: bool
        """
        prev = -float("inf")
        n = len(s)
        p = 0
        while p < n:
            if s[p].isdigit():
                cur = ""
                while p < n and s[p].isdigit():
                    cur += s[p]
                    p += 1
                cur = int(cur)
                if cur <= prev:
                    return False
                prev = cur
            else:
                p += 1
        return True
